"""Select and validate a finite higher-return pure-stock analyst portfolio grid."""
from __future__ import annotations
import argparse,json
from pathlib import Path
import pandas as pd
from experiments.quarterly_portfolio import BasketConfig,simulate_basket
from experiments.run_analyst_revision import benchmark_returns,build_inputs,load_reports
from experiments.run_largecap_lowvol import summarize_basket
from experiments.run_market_gated_analyst import revision_breadth_states
def encode(value):return value.item() if hasattr(value,"item") else str(value)
FOLDS=(("discovery","2017-01-01","2022-12-31"),("validation","2023-01-01","2024-12-31"),("holdout","2025-01-01","2025-12-31"));BASELINE_CAGR=.1432
def yearly_return(returns,year):
 x=returns[pd.to_datetime(returns.index).year==year];return float((1+x).prod()-1) if len(x) else 0.0
def run(raw_dir,start,end,benchmark_path,signals_path,nav_path,out_json,out_md,current_json,current_md):
 reports=load_reports(raw_dir);dates,lookup,base_targets,signals,metadata=build_inputs(start,end,reports,"revision");signals.to_csv(signals_path,index=False,date_format="%Y-%m-%d");states,_=revision_breadth_states(signals,base_targets);benchmark=benchmark_returns(benchmark_path,dates);variants={};results={}
 for gate_mode in ["always","revision_breadth"]:
  for top_k in [10,20,30]:
   name=f"{gate_mode}_top{top_k}";targets={date:(symbols[:top_k] if gate_mode=="always" or states[date] else []) for date,symbols in base_targets.items()};config=BasketConfig(name=name,target_count=top_k,initial_nav=400000,buy_cost=.00155,sell_cost=.00155);gross_config=BasketConfig(name=name+"_gross",target_count=top_k,initial_nav=400000,buy_cost=0,sell_cost=0);result=simulate_basket(dates,lookup,targets,config);gross=simulate_basket(dates,lookup,targets,gross_config);portfolio=summarize_basket(result,gross,benchmark,config,folds=FOLDS);participation=sum(bool(v) for v in targets.values())/len(targets);variants[name]={"top_k":top_k,"gate_mode":gate_mode,"participation":participation,"portfolio":portfolio};results[name]=(result,gross,targets)
 eligible=[]
 for name,value in variants.items():
  discovery=value["portfolio"]["folds"]["discovery"]
  if discovery["cagr"]>=.10 and discovery["excess_cagr"]>0 and discovery["max_drawdown"]>=-.50 and value["portfolio"]["gross_to_net_cagr_retention"]>=.75:eligible.append(name)
 selected=max(eligible,key=lambda name:(variants[name]["portfolio"]["folds"]["discovery"]["cagr"],variants[name]["portfolio"]["folds"]["discovery"]["sharpe"],variants[name]["portfolio"]["folds"]["discovery"]["max_drawdown"],-variants[name]["top_k"]));choice=variants[selected];portfolio=choice["portfolio"];result,gross,targets=results[selected];pd.DataFrame({"date":result.dates,"nav":result.nav,"gross_nav":gross.nav,"benchmark_return":benchmark.to_numpy()}).to_csv(nav_path,index=False);validation=portfolio["folds"]["validation"];holdout_return=float(portfolio["yearly_returns"].get("2025",0));benchmark_2025=yearly_return(benchmark,2025);checks={"higher_cagr":portfolio["metrics"]["cagr"]>BASELINE_CAGR,"validation":validation["cagr"]>0 and validation["excess_cagr"]>0,"holdout":holdout_return>0 and holdout_return>benchmark_2025,"sharpe":portfolio["metrics"]["sharpe"]>=.60,"drawdown":portfolio["metrics"]["max_drawdown"]>=-.50,"cost_retention":portfolio["gross_to_net_cagr_retention"]>=.80,"turnover":portfolio["annual_turnover"]<=12};payload={"study":"a-share-higher-return-analyst-grid-v13","authority":"exploratory_only_no_platform_prepare_operation","data":metadata,"selection":{"eligible":eligible,"policy":"discovery CAGR, Sharpe, max drawdown, fewer holdings","selected":selected},"variants":variants,"selected_result":{"name":selected,"portfolio":portfolio,"holdout_2025":{"strategy_return":holdout_return,"benchmark_return":benchmark_2025,"excess":holdout_return-benchmark_2025}},"checks":checks,"verdict":"GO-HIGHER-RETURN-CANDIDATE" if all(checks.values()) else "NO-GO","trade_authorized":False};Path(out_json).write_text(json.dumps(payload,ensure_ascii=False,indent=2,default=encode)+"\n");m=portfolio["metrics"];lines=["# A股更高收益分析师组合V13结果","",f"- verdict: **{payload['verdict']}**",f"- selected: **{selected}**",f"- CAGR/Sharpe/MDD: {m['cagr']:.2%} / {m['sharpe']:.3f} / {m['max_drawdown']:.2%}",f"- validation CAGR/excess: {validation['cagr']:.2%} / {validation['excess_cagr']:.2%}",f"- 2025 strategy/benchmark: {holdout_return:.2%} / {benchmark_2025:.2%}"];Path(out_md).write_text("\n".join(lines)+"\n");last=max(targets);current={"as_of":end,"selected":selected,"last_decision":last,"targets":targets[last],"strategy_verdict":payload["verdict"],"trade_authorized":False};Path(current_json).write_text(json.dumps(current,ensure_ascii=False,indent=2)+"\n");Path(current_md).write_text("# A股更高收益分析师组合当前状态\n\n"+f"- selected: {selected}\n- targets: {len(targets[last])}\n- trade authorized: **NO**\n");print("\n".join(lines));return payload
def main(argv=None):
 p=argparse.ArgumentParser();p.add_argument("--raw-dir",default="overall/a-share-report-rc-raw");p.add_argument("--start",default="2017-01-03");p.add_argument("--end",default="2026-08-26");p.add_argument("--benchmark",default="overall/a-share-equity-etf-daily-current.csv");p.add_argument("--signals",default="overall/a-share-higher-return-analyst-signals.csv");p.add_argument("--nav",default="overall/a-share-higher-return-analyst-nav.csv");p.add_argument("--out-json",default="overall/a-share-higher-return-analyst-grid-v13-result.json");p.add_argument("--out-md",default="overall/a-share-higher-return-analyst-grid-v13-result.md");p.add_argument("--current-json",default="overall/a-share-higher-return-analyst-current.json");p.add_argument("--current-md",default="overall/a-share-higher-return-analyst-current.md");a=p.parse_args(argv);run(a.raw_dir,a.start,a.end,a.benchmark,a.signals,a.nav,a.out_json,a.out_md,a.current_json,a.current_md);return 0
if __name__=="__main__":raise SystemExit(main())
